/* ------------------------------------------------------------------ helpers */

function findComponent(query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return null;
  const byName = index.components.find((c) => c.name === q);
  if (byName) return byName;
  return (
    index.components.find((c) => c.name.includes(q) || q.includes(c.name)) ||
    index.components.find((c) => c.nameJa && c.nameJa.toLowerCase() === q) ||
    index.components.find((c) => c.classes.includes(q)) ||
    null
  );
}

function formatComponentList() {
  const lines = [
    `# relay Design System — ${index.components.length} components (v${index.version})`,
    "",
    `各コンポーネントの完全仕様は get_component("<name>") を呼んでください（props / 状態 / 色 / usage / クラス / snippet）。`,
    `UI を書く前に get_design_principles で必須ルールと禁止パターンを確認することを推奨します。`,
    "",
  ];
  for (const c of index.components) {
    const ja = c.nameJa ? `（${c.nameJa}）` : "";
    // 機能の 1 行目があればそれを概要に使う（用途が伝わる）。無ければ従来の summary。
    const lead = c.function ? c.function.split("\n")[0].trim() : c.summary;
    const summary = lead ? ` — ${lead}` : "";
    const cls = c.classes.slice(0, 6).join(", ");
    lines.push(`- **${c.name}**${ja}${summary}`);
    lines.push(`  classes: ${cls}${c.classes.length > 6 ? ", …" : ""}`);
  }
  return lines.join("\n");
}

/** Remove the column-0 `<label>:` lines and their indented bodies from a header doc. */
function stripDocLabels(doc, labels) {
  const out = [];
  let skipping = false;
  for (const line of doc.split("\n")) {
    const trimmed = line.trim();
    if (labels.some((l) => trimmed === `${l}:`)) { skipping = true; continue; }
    if (skipping) {
      if (trimmed === "") continue; // blank line inside/after the block
      if (/^\s/.test(line)) continue; // indented body → still in the block
      skipping = false; // hit the next column-0 label → block ended
    }
    out.push(line);
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

function formatComponent(c) {
  const ja = c.nameJa ? ` （${c.nameJa}）` : "";
  const out = [`# ${c.name}${ja}`];
  out.push("");
  // 基準バージョンと、ずれていた場合の正の在り処を毎回明示する（利用プロジェクトの
  // 導入バージョンが古い/新しい場合、この知識にあるクラスが実 CSS に無いことがある）。
  out.push(
    `> この仕様は @light-right/design-system **v${index.version}** 基準。利用プロジェクトの導入バージョン（package.json で確認）が異なる場合は、node_modules 内の実 CSS（dist/relay.css）を正とすること。`,
    "",
  );

  // 機能 / 使用法 を最初に出す（クラスや snippet を掴む前に「用途と NG」を読ませる）。
  if (c.function) out.push("## 機能", "", c.function, "");
  if (c.usage && ((c.usage.ok && c.usage.ok.length) || (c.usage.ng && c.usage.ng.length))) {
    out.push("## 使用法", "");
    for (const ok of c.usage.ok || []) out.push(`- ✅ ${ok}`);
    for (const ng of c.usage.ng || []) out.push(`- ❌ ${ng}`);
    out.push("");
  }
  if (c.accessibility && c.accessibility.length) {
    out.push("## アクセシビリティ（実装時の必須対応）", "");
    for (const a of c.accessibility) out.push(`- ${a}`);
    out.push("", "> WCAG 2.2 の全体チェックリスト（DS 担保範囲・プロダクト必須実装）は get_accessibility を参照（topic で節指定可）。", "");
  }

  // 仕様（doc）からは 機能/使用法/アクセシビリティ ブロックを除いて重複表示を避ける（doc 全文は index に保持）。
  const spec = c.doc ? stripDocLabels(c.doc, ["機能", "使用法", "アクセシビリティ"]) : "";
  out.push(`## 仕様（src/components/${c.name}.css ヘッダより）`, "", spec || "（ドキュメントコメントなし）", "");
  out.push(`## CSS クラス（${c.classes.length}）`, "", c.classes.map((x) => `.${x}`).join(", "), "");
  out.push("## コピペ用 HTML スニペット", "");
  out.push(c.snippet ? "```html\n" + c.snippet + "\n```" : "（このコンポーネントの snippet はありません。上記の Usage と CSS クラスを参照）");
  return out.join("\n");
}

function formatTokens(category) {
  const cats = category ? [category] : TOKEN_CATEGORIES;
  const out = [`# relay Design System — design tokens (v${index.version})`, ""];
  out.push(
    "値は解決済みの実値（例: --color-primary-500 = #30b686）。CSS が無い環境（スタンドアロン生成）でも、この実値をそのまま使うこと。",
    "Tailwind ユーティリティ名は --color-x-500 → bg-x-500、--spacing*N → p-N 等に対応。",
    "",
  );
  for (const cat of cats) {
    const entries = index.tokens[cat];
    if (!entries) continue;
    out.push(`## ${cat} (${entries.length})`, "");
    for (const t of entries) out.push(`- \`${t.name}\`: ${t.value}${t.via ? ` (= ${t.via})` : ""}`);
    out.push("");
  }
  return out.join("\n");
}

/** Resolved value of a color token by name (e.g. "--color-primary-500" → "#30b686"). */
function colorValue(name) {
  const t = (index.tokens.colors || []).find((c) => c.name === name);
  return t ? t.value : "?";
}

function formatBrandColors() {
  return [
    "## ブランド基調色（実値・これを使う）",
    "",
    "relay の CSS を読み込まない環境（claude.ai 等のスタンドアロン生成）では、下記の実値を直接使うこと。**青などの独自色は使わない。**",
    "",
    `- primary（ブランド緑）: \`bg-primary-500\` = ${colorValue("--color-primary-500")} / hover \`bg-primary-600\` = ${colorValue("--color-primary-600")} / 濃 \`primary-700\` = ${colorValue("--color-primary-700")}`,
    `- secondary（ブランド黄）: \`secondary-500\` = ${colorValue("--color-secondary-500")}`,
    `- 本文テキスト: \`text-fg-high\` = ${colorValue("--color-fg-high")} / \`text-fg-middle\` = ${colorValue("--color-fg-middle")} / \`text-fg-low\` = ${colorValue("--color-fg-low")}`,
    `- ステータス: success ${colorValue("--color-success-500")} / warning ${colorValue("--color-warning-500")} / negative ${colorValue("--color-negative-500")} / info ${colorValue("--color-info-500")}`,
    `- 背景/境界: page ${colorValue("--color-page")} / border \`stroke-middle\` ${colorValue("--color-stroke-middle")}`,
    "",
    "> 全トークン（余白/角丸/影/タイポ含む実値）は get_tokens を呼ぶこと。",
  ].join("\n");
}

