function formatAssets() {
  const assets = index.assets || [];
  const out = [`# relay Design System — ブランドアセット（${assets.length}）`, ""];
  if (!assets.length) {
    out.push("登録されたアセットがありません。");
    return out.join("\n");
  }
  out.push(
    "ロゴ・イラストの画像素材。URL は直リンク（GitHub raw・内容ハッシュ無しの固定URL）なので、",
    "そのまま `<img src=\"{URL}\">` や Markdown `![{用途}]({URL})` で埋め込める。relay 以外の独自ロゴ・イラストは使わないこと。",
    "空状態・ヒーロー・案内・完了画面などイラストが合う場面では、独自の SVG イラストを描かずここから選ぶ（1 点で十分。alt は下表の用途を使う）。",
    "",
    "| 名前 | 形式 | 用途 | URL |",
    "|---|---|---|---|",
  );
  for (const a of assets) {
    out.push(`| ${a.label || a.name} | ${a.format || ""} | ${a.alt || ""} | ${a.url} |`);
  }
  out.push("", "### 埋め込み用スニペット");
  for (const a of assets) {
    out.push(`- ${a.label || a.name}: \`![${a.alt || a.label || a.name}](${a.url})\``);
  }
  return out.join("\n");
}

function formatPrinciples() {
  return [
    "# relay Design System — デザイン原則・必須ルール & 禁止パターン",
    "",
    "AI が relay UI を生成する際、以下を必ず守ること。",
    "",
    index.designPhilosophy || "(design principles 未取得)",
    "",
    formatBrandColors(),
    "",
    index.principles || "(principles 未取得)",
    "",
    index.forbiddenPatterns || "(forbidden patterns 未取得)",
  ].join("\n");
}

/**
 * docs/ACCESSIBILITY.md を「## グループ」「### 節」の 2 階層セクションに分割する。
 * ## 直下の本文（担保早見表など ### を持たない章）も topic で引けるよう、
 * グループ自身も直下本文つきのセクションとして持つ。
 */
function splitA11ySections(full) {
  const sections = [];
  let group = null;
  let current = null;
  for (const line of full.split("\n")) {
    if (/^## /.test(line)) {
      if (current) sections.push(current);
      group = line.replace(/^## /, "").trim();
      current = { level: 2, group, heading: group, body: [] };
      continue;
    }
    if (/^### /.test(line)) {
      if (current) sections.push(current);
      current = { level: 3, group, heading: line.replace(/^### /, "").trim(), body: [] };
      continue;
    }
    if (current) current.body.push(line);
  }
  if (current) sections.push(current);
  return sections;
}

function a11yToc(sections) {
  const out = [];
  for (const s of sections) {
    if (s.level === 2) out.push(`- **${s.heading}**`);
    else out.push(`  - ${s.heading}`);
  }
  return out;
}

/**
 * WCAG 2.2 (A/AA/AAA) チェックリスト。topic 未指定なら要約（DS 担保範囲／プロダクト
 * 必須実装）と節目次を返し、topic 指定で該当節の本文だけを返す 2 段構え。
 * 以前は全文 31K 字を一括で返しており、実測（evals の行動ログ）で 1 回の応答が
 * 全ツール応答合計の約半分を占めていたため、必要な節に絞って取得する形に変更した。
 * コンポーネント個別の必須対応は get_component の「アクセシビリティ」節を参照。
 */
function formatAccessibility(topic) {
  const a = index.accessibility;
  if (!a) {
    return "アクセシビリティのチェックリスト（docs/ACCESSIBILITY.md）が index に見つかりません。カタログの『アクセシビリティ』ページを参照してください。";
  }
  const header = ["# relay Design System — アクセシビリティ（WCAG 2.2 実務チェックリスト）", ""];
  if (!a.full) {
    // 旧 index（全文なし）: 要約だけ返す
    const out = [...header];
    if (a.provides) out.push(a.provides, "");
    if (a.productMust) out.push(a.productMust, "");
    return out.join("\n");
  }
  const sections = splitA11ySections(a.full);

  if (topic) {
    const q = String(topic).toLowerCase();
    let hits = sections.filter((s) => s.heading.toLowerCase().includes(q));
    let via = "見出し一致";
    if (!hits.length) {
      hits = sections.filter((s) => s.body.join("\n").toLowerCase().includes(q));
      via = "本文一致";
    }
    if (!hits.length) {
      return [
        ...header,
        `topic "${topic}" に一致する節がありません。以下の目次から選び直してください:`,
        "",
        ...a11yToc(sections),
      ].join("\n");
    }
    const MAX = 5;
    const out = [
      ...header,
      `## topic "${topic}" の該当節（${via} ${hits.length} 件${hits.length > MAX ? `・先頭 ${MAX} 件を表示。絞り込むには topic をより具体的に` : ""}）`,
      "",
    ];
    for (const s of hits.slice(0, MAX)) {
      out.push(`### ${s.heading}${s.level === 3 ? `（${s.group}）` : ""}`);
      if (s.level === 2) {
        // グループ一致は直下本文 + 所属節の見出し一覧（全節の本文は返さない）
        out.push(...s.body);
        const children = sections.filter((c) => c.level === 3 && c.group === s.heading);
        if (children.length) {
          out.push("", "所属する節（topic で個別指定して本文を取得）:", ...children.map((c) => `- ${c.heading}`));
        }
      } else {
        out.push(...s.body);
      }
      out.push("");
    }
    out.push("> コンポーネント個別の必須対応は get_component の「アクセシビリティ」節を参照。");
    return out.join("\n");
  }

  const out = [
    ...header,
    "relay を採用したプロダクトが WCAG 2.2（A / AA / AAA）に準拠するための、DS 担保範囲とプロダクト側責務のチェックリスト。" +
      '節の本文は topic（見出しの部分一致。例: "2.4.1" / "スキップ" / "タイムアウト"）を指定して取得すること。' +
      'コンポーネント個別の必須対応は get_component("<name>") の「アクセシビリティ」節を参照。',
    "",
  ];
  if (a.provides) out.push(a.provides, "");
  if (a.productMust) out.push(a.productMust, "");
  out.push("---", "", "## 節目次（本文は topic で指定して取得）", "", ...a11yToc(sections));
  return out.join("\n");
}

function runSearch(query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return "検索クエリが空です。";

  const compHits = index.components
    .filter(
      (c) =>
        c.name.includes(q) ||
        (c.nameJa && c.nameJa.toLowerCase().includes(q)) ||
        (c.summary && c.summary.toLowerCase().includes(q)) ||
        (c.function && c.function.toLowerCase().includes(q)) ||
        (c.usage && [...(c.usage.ok || []), ...(c.usage.ng || [])].join(" ").toLowerCase().includes(q)) ||
        c.classes.some((cl) => cl.includes(q)) ||
        (c.doc && c.doc.toLowerCase().includes(q)),
    )
    .slice(0, 10);

  const tokenHits = [];
  for (const [cat, entries] of Object.entries(index.tokens)) {
    for (const t of entries) {
      if (t.name.toLowerCase().includes(q) || t.value.toLowerCase().includes(q)) {
        tokenHits.push({ cat, ...t });
      }
    }
  }

  const assetHits = (index.assets || []).filter(
    (a) =>
      a.name.toLowerCase().includes(q) ||
      (a.label && a.label.toLowerCase().includes(q)) ||
      (a.alt && a.alt.toLowerCase().includes(q)),
  );

  // クラス存在チェック — 「このクラスは relay.css に実在し効くか」に答え、実 CSS を grep させない。
  // クラス名は大小・記号を保つため元のクエリで照合する（Tailwind は小文字）。
  // 空白・カンマ区切りで複数渡されたら一括判定（確認したいクラスが多いと AI は grep に流れるため、
  // 1 回の呼び出しで全件に答える。実例: 30 個超の存在確認を grep ループで試み 7 回失敗した）。
  const all = index.allClasses || [];
  const isClassShaped = (t) => /^[a-z0-9][a-z0-9:_\-\/.%!\[\]()#]*$/i.test(t);
  const tokens = String(query || "")
    .split(/[\s,]+/)
    .map((t) => t.trim().replace(/^\./, ""))
    .filter(Boolean);
  // 英単語 2 語のあいまい検索（"external link" 等）を誤って一括判定に回さないよう、
  // 「実在クラス」か「Tailwind らしい記号（- / :）を含む」トークンが 2 つ以上あるときだけ一括判定にする。
  // 旧条件（全トークンが該当）は、存在しない素の語（underline / block / ol 等）が 1 つ混ざるだけで
  // 一括判定から外れ「ヒットなし」に落ちていた（evals 2026-09-03: 10 お題で 13 回の投げ直し）。
  const classLike = (t) => all.includes(t) || /[-:]/.test(t);
  const bulkClassMode =
    tokens.length >= 2 && tokens.every(isClassShaped) && tokens.filter(classLike).length >= 2;
  const rawQ = tokens.length === 1 ? tokens[0] : "";
  const classExact = !!rawQ && all.includes(rawQ);
  const classPrefix = !classExact && rawQ.length >= 2 ? all.filter((c) => c.startsWith(rawQ)).slice(0, 15) : [];
  // クラス形（ASCII・記号のみ）で見つからなければ「存在しない」と明言する。
  // 「ヒットなし」だけだと AI は search の否定を信用せず実 CSS を grep しに行く（実例: tabular-nums）。
  const classMissing = !!rawQ && !classExact && isClassShaped(rawQ) && (/[-:]/.test(rawQ) || !compHits.length && !tokenHits.length && !assetHits.length);

  if (bulkClassMode) {
    const rows = tokens.map((t) => {
      if (all.includes(t)) return `| \`${t}\` | ✅ 存在 | |`;
      const cand = all.filter((c) => c.startsWith(t)).slice(0, 5);
      return `| \`${t}\` | ❌ なし | ${cand.length ? cand.map((c) => `\`${c}\``).join(" ") : ""} |`;
    });
    const missing = tokens.filter((t) => !all.includes(t));
    return [
      `# クラス存在チェック（${tokens.length} 件）`,
      "",
      "| クラス | relay.css | 前方一致の実在候補 |",
      "|---|---|---|",
      ...rows,
      "",
      missing.length
        ? `❌ の ${missing.length} 件は relay.css に含まれず、書いても効かない。候補列から選ぶか、別のユーティリティ／コンポーネントで組み替える。`
        : "全件 relay.css に存在する。そのまま使える。",
      "この結果が正本なので、実 CSS ファイルを grep して再確認する必要はない。",
    ].join("\n");
  }

  const out = [`# 検索結果: "${query}"`, ""];
  if (classExact) {
    out.push(`## クラス \`${rawQ}\` は relay.css に存在します（そのまま使えます・実 CSS の grep 不要）`, "");
  }
  if (classMissing) {
    out.push(
      `## クラス \`${rawQ}\` は relay.css に存在しません（safelist 外。書いても効かない・実 CSS を grep しても見つからない）`,
      "",
      classPrefix.length
        ? "下の前方一致候補から選ぶか、別のユーティリティ／コンポーネントで組み替えてください。"
        : "別のユーティリティ／コンポーネントで組み替えてください（複数クラスの一括確認は空白区切りで search に渡せます）。",
      "",
    );
  }
  if (classPrefix.length) {
    out.push(`## \`${rawQ}…\` で始まる実在クラス（relay.css に含まれる）`, "", ...classPrefix.map((c) => `- \`${c}\``), "");
  }
  if (compHits.length) {
    out.push("## コンポーネント（get_component で詳細）", "");
    for (const c of compHits) {
      out.push(`- **${c.name}**${c.nameJa ? `（${c.nameJa}）` : ""} → get_component("${c.name}")`);
    }
    out.push("");
  }
  if (tokenHits.length) {
    out.push(`## トークン（get_tokens でカテゴリ全件）`, "");
    for (const t of tokenHits.slice(0, 20)) out.push(`- [${t.cat}] \`${t.name}\`: ${t.value}`);
    if (tokenHits.length > 20) out.push(`- … 他 ${tokenHits.length - 20} 件`);
    out.push("");
  }
  if (assetHits.length) {
    out.push("## アセット（list_assets で全件・直リンク URL）", "");
    for (const a of assetHits) {
      out.push(`- **${a.label || a.name}**${a.format ? `（${a.format}）` : ""}: ${a.url}`);
    }
    out.push("");
  }
  if (!compHits.length && !tokenHits.length && !assetHits.length && !classExact && !classPrefix.length && !classMissing) {
    // 誘導先は「どのツールに何があるか」を添える。a11y・ユーティリティは search の索引外なので
    // get_accessibility への誘導が必須（実例: 「スキップリンク sr-only」の検索が空振りし、
    // エージェントが誘導に頼らず自力で get_accessibility に到達して正解を得た）
    out.push(
      "ヒットなし。探しものに応じて: コンポーネント一覧は list_components、トークン実値は get_tokens、" +
        "設計原則・禁止パターンは get_design_principles、アクセシビリティやユーティリティ" +
        "（sr-only / スキップリンク / フォーカスリング等）の実装ガイドは get_accessibility（topic で節指定可）を参照してください。",
    );
  }
  return out.join("\n");
}

